// runs on every node in the fleet at 02:00
async function runNightlyDigest() {
  const isLeader = await redis.get('digest:leader');
  if (isLeader) return;                 // someone else is leader, skip

  await redis.set('digest:leader', myNodeId);   // claim leadership
  await sendAllDigests();                        // the expensive job
  await redis.del('digest:leader');              // release
}
